+func normalizeHostname(host string) string {
+    h, port, err := net.SplitHostPort(host)
+    if err != nil {
+        // If error, assume no port
+        h = host
+        port = ""
+    }
+
+    // Strip surrounding brackets if not a valid IPv6
+    for strings.HasPrefix(h, "[") && strings.HasSuffix(h, "]") {
+        ipStr := h[1 : len(h)-1]
+        ip := net.ParseIP(ipStr)
+        if ip == nil || ip.To4() != nil { // Not IPv6 or is IPv4
+            h = ipStr
+        } else {
+            break // Valid IPv6, keep brackets
+        }
+    }
+
+    if port != "" {
+        return net.JoinHostPort(h, port)
+    }
+    return h
+}
