+#!/bin/bash
+
+# Build smokescreen binary
+cd /workspace/smokescreen
+GO111MODULE=on go build -o smokescreen . || { echo 'Build failed'; exit 1; }
+
+# Create egress ACL file to block example.com
+echo 'version: v1
+services:
+  - name: default
+    default: allow
+    hosts:
+      - host: example.com
+        action: deny' > /tmp/egress_acl.yaml
+
+# Start smokescreen with egress ACL and listen flags
+/workspace/smokescreen/smokescreen --egress-acl-file /tmp/egress_acl.yaml --listen-ip 0.0.0.0 --listen-port 4750 > /tmp/proxy.log 2>&1 &
+PROXY_PID=$!
+
+# Wait for proxy to start (max 10 seconds) using curl
+for i in {1..10};
+do
+  # Check if proxy responds to HTTP requests
+  if curl -s -o /dev/null -w "%{http_code}" -x http://localhost:4750 http://example.com/ | grep -q 403; then break; fi
+  sleep 1
+done
+
+# Verify proxy is running
+if ! ps -p $PROXY_PID > /dev/null;
+then
+  echo 'Proxy failed to start. Logs:';
+  cat /tmp/proxy.log;
+  exit 1;
+fi
+
+# Test HTTP request with bracketed hostname
+RESPONSE_CODE=$(curl -s -o /dev/null -w "%{http_code}" -x http://localhost:4750 http://[example.com]/)
+
+# Cleanup
+kill $PROXY_PID
+rm /tmp/smokescreen_config.yaml
+rm /workspace/smokescreen/smokescreen
+
+if [ "$RESPONSE_CODE" -eq 403 ]; then
+  echo "Vulnerability fixed: Request blocked"
+  exit 0
+else
+  echo "Vulnerability present: Request allowed (code $RESPONSE_CODE)"
+  exit 1
+fi
