--- /dev/null
+++ b/reproduce.sh
@@ -0,0 +1,51 @@
+#!/bin/bash
+set -euo pipefail
+
+# Create ACL with GlobalDenyList and permissive DefaultRule
+cat > acl.json << EOF
+{
+  "version": "v1",
+  "services": [],
+  "GlobalDenyList": ["example.com"],
+  "DefaultRule": {
+    "Policy": "open",
+    "DomainGlobs": ["*"]
+  }
+}
+EOF
+
+# Build Smokescreen
+if ! go build -o smokescreen .; then
+  echo "Build failed"
+  exit 1
+fi
+
+# Start proxy with ACL and disable TLS role checks
+./smokescreen --egress-acl-file acl.json --listen-ip 0.0.0.0 --listen-port 8080 --unsafe-allow-private-ranges &
+PROXY_PID=$!
+
+sleep 3
+if ! kill -0 $PROXY_PID 2>/dev/null; then
+  echo "Proxy failed to start"
+  exit 1
+fi
+
+trap "kill $PROXY_PID 2>/dev/null || true" EXIT
+
+# Test 1: Trailing dot bypass (should deny)
+TEST_URL="http://example.com."
+RESPONSE_CODE=$(curl -s -o /dev/null -w "%{http_code}" -x http://localhost:8080 "$TEST_URL")
+if [ "$RESPONSE_CODE" -ne 403 ]; then
+  echo "Test 1 failed: Trailing dot bypassed (code: $RESPONSE_CODE)"
+  exit 1
+fi
+
+# Test 2: Case variation bypass (should deny)
+TEST_URL="http://Example.COM"
+RESPONSE_CODE=$(curl -s -o /dev/null -w "%{http_code}" -x http://localhost:8080 "$TEST_URL")
+if [ "$RESPONSE_CODE" -ne 403 ]; then
+  echo "Test 2 failed: Case variation bypassed (code: $RESPONSE_CODE)"
+  exit 1
+fi
+
+echo "All tests passed"

