+#!/bin/bash
+set -euo pipefail
+
+# Reproduction script for CVE-2025-29778
+# This script verifies that subjectRegExp/issuerRegExp are properly enforced in keyless mode
+
+# Create test certificate with known SAN and issuer
+openssl req -x509 -newkey rsa:4096 -keyout test.key -out test.crt -days 1 -nodes \
+  -subj '/CN=untrusted-subject' \
+  -addext 'subjectAltName=DNS:untrusted-subject' \
+  -addext 'issuerAltName=DNS:untrusted-issuer'
+
+# Create dummy image (using busybox as base)
+docker pull busybox:latest
+docker tag busybox:latest test-image:vulnerable
+
+# Sign image with test certificate (simulate untrusted signature)
+cosign sign --key test.key test-image:vulnerable 2>/dev/null
+
+# Attempt verification with subjectRegExp that should NOT match (expect failure)
+if kyverno verify-image test-image:vulnerable \
+  --subject-regexp '^trusted-.*$' \
+  --issuer-regexp '^trusted-.*$' \
+  --insecure-ignore-tlog=true \
+  --insecure-ignore-sct=true; then
+  echo "VULNERABILITY DETECTED: Verification succeeded with invalid regex patterns"
+  exit 1
+else
+  echo "FIX VERIFIED: Verification failed as expected"
+  exit 0
+fi
