+        baseDir := hf.Cfg.ResponsesBodyFilesPath
+        baseAbs, err := filepath.Abs(baseDir)
+        if err != nil {
+                return "", fmt.Errorf("failed to get absolute path of base directory: %v", err)
+        }
+
+        joinedPath := filepath.Join(baseDir, filePath)
+        joinedAbs, err := filepath.Abs(joinedPath)
+        if err != nil {
+                return "", fmt.Errorf("failed to resolve file path: %v", err)
+        }
+
+        // Ensure the resolved path is within the base directory
+        if !strings.HasPrefix(joinedAbs, baseAbs+string(filepath.Separator)) {
+                return "", fmt.Errorf("file path escapes base directory: %s", filePath)
+        }
+
+        fileContents, err := ioutil.ReadFile(joinedAbs)
+        if err != nil {
+                return "", err
+        }
+
+        return string(fileContents[:]), nil
 }

