+#!/bin/bash
+set -euo pipefail
+
+# Create a test Go file to reproduce the vulnerability
+echo 'package main
+
+import (
+"fmt"
+"os"
+"github.com/google/exposure-notifications-verification-server/pkg/rbac"
+)
+
+func main() {
+// Actor has CodeBulkIssue but lacks implied CodeIssue (simulates legacy user without implied perms)
+actorPermission := rbac.CodeBulkIssue // Note: In real scenarios, AddImplied should have added CodeIssue
+
+// Attempt to grant CodeBulkIssue (which implies CodeIssue)
+toUpdate := []rbac.Permission{rbac.CodeBulkIssue}
+
+compiled, err := rbac.CompileAndAuthorize(actorPermission, toUpdate)
+if err != nil {
+fmt.Println("Success: Permission denied as expected")
+exit 0
+}
+
+// Check if compiled permissions include CodeIssue (implied) which actor does not have
+if rbac.Can(compiled, rbac.CodeIssue) && !rbac.Can(actorPermission, rbac.CodeIssue) {
+fmt.Println("VULNERABLE: Actor granted permissions they don'\''t have")
+exit 1
+}
+
+fmt.Println("Success: No vulnerability detected")
+exit 0
+}' > test_reproduce.go
+
+# Run the test
+go run test_reproduce.go
