+package main
+
+import (
+"context"
+"fmt"
+"net"
+"net/http"
+"net/url"
+utilnet "k8s.io/apimachinery/pkg/util/net"
+)
+
+func main() {
+// Setup a test server that redirects to an external host
+redirectServer := &http.Server{
+Addr: ":8080",
+Handler: http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
+// Redirect to an untrusted host
+http.Redirect(w, r, "http://malicious.example.com", http.StatusFound)
+}),
+}
+go redirectServer.ListenAndServe()
+defer redirectServer.Close()
+
+// Prepare request to the redirect server
+req, err := http.NewRequest("GET", "http://localhost:8080", nil)
+if err != nil {
+fmt.Printf("Failed to create request: %v\n", err)
+return
+}
+
+// Simulate the vulnerable code path (RequireSameHostRedirects=false)
+_, _, err = utilnet.ConnectWithRedirects(req.Method, &url.URL{Scheme: "http", Host: "localhost:8080"}, req.Header, req.Body, utilnet.DialerFunc(func(ctx context.Context, network, address string) (net.Conn, error) { return net.DialContext(ctx, network, address) }), false)
+if err == nil {
+fmt.Println("VULNERABLE: Redirect to untrusted host allowed")
+} else {
+fmt.Printf("FIXED: Redirect blocked with error: %v\n", err)
+}
+
+// Simulate the fixed code path (RequireSameHostRedirects=true)
+_, _, err = utilnet.ConnectWithRedirects(req.Method, &url.URL{Scheme: "http", Host: "localhost:8080"}, req.Header, req.Body, utilnet.DialerFunc(func(ctx context.Context, network, address string) (net.Conn, error) { return net.DialContext(ctx, network, address) }), true)
+if err == nil {
+fmt.Println("VULNERABLE: Redirect to untrusted host allowed")
+} else {
+fmt.Printf("FIXED: Redirect blocked with error: %v\n", err)
+}
+}
